import React, { useState, useEffect } from "react";
import axios from "axios";

function ReservationPage() {
  const [tableId, setTableId] = useState("");
  const [customerName, setCustomerName] = useState("");
  const [time, setTime] = useState("");
  const [reservations, setReservations] = useState([]);

  // Load reservations when page opens
  useEffect(() => {
    axios.get("http://localhost:5000/api/reservations")
      .then(res => setReservations(res.data))
      .catch(err => console.error("Error fetching reservations:", err));
  }, []);

  // Reserve a table
  const reserveTable = () => {
    if (!tableId || !customerName || !time) {
      alert("Please fill in all fields");
      return;
    }
    axios.post("http://localhost:5000/api/reservations", {
      table_id: parseInt(tableId, 10),
      customer_name: customerName,
      time: time
    })
    .then(res => {
      alert(`Reservation confirmed! ID: ${res.data.id}`);
      setTableId("");
      setCustomerName("");
      setTime("");
      refreshReservations();
    })
    .catch(err => alert("Error making reservation: " + err.message));
  };

  // Refresh reservations list
  const refreshReservations = () => {
    axios.get("http://localhost:5000/api/reservations")
      .then(r => setReservations(r.data));
  };

  return (
    <div style={{ maxWidth: "500px", margin: "0 auto", padding: "20px" }}>
      <h2>Table Reservation</h2>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px", marginBottom: "20px" }}>
        <input
          type="number"
          placeholder="Table ID"
          value={tableId}
          onChange={e => setTableId(e.target.value)}
        />
        <input
          type="text"
          placeholder="Customer Name"
          value={customerName}
          onChange={e => setCustomerName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Time (e.g. 7:30 PM)"
          value={time}
          onChange={e => setTime(e.target.value)}
        />
        <button
          onClick={reserveTable}
          style={{
            background: "#4a148c",
            color: "white",
            padding: "10px",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer"
          }}
        >
          Reserve
        </button>
      </div>

      <h3>Reserved Tables</h3>
      {reservations.length === 0 ? (
        <p>No reservations yet.</p>
      ) : (
        <ul>
          {reservations.map(r => (
            <li key={r.id}>
              Table {r.table_id} — {r.customer_name} at {r.time}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default ReservationPage;
